(()=>{"use strict";const cfg=window.MUNDO_DIGITAL_CONFIG||{};const $=s=>document.querySelector(s);const E={menu:$("#menuLateral"),capa:$("#capaOscura"),abrir:$("#botonAbrirMenu"),cerrar:$("#botonCerrarMenu"),salir:$("#botonCerrarSesion"),guardar:$("#guardarConfiguracionTienda"),tasa:$("#tasaBsConfig"),mostrar:$("#mostrarBsConfig"),max:$("#maxMbConfig"),fecha:$("#fechaTasaConfig"),carpeta:$("#abrirCarpetaConfig"),lista:$("#listaMetodosConfig"),estado:$("#estadoConfig"),punto:$("#puntoConfig"),mensaje:$("#mensajeConfig")};let metodos=[];function aviso(t,e=false){E.mensaje.textContent=t;E.mensaje.className=`mensaje-config visible ${e?"error":""}`;setTimeout(()=>E.mensaje.className="mensaje-config",3500)}function esc(v){return String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;")}async function get(a){const u=new URL(cfg.APPS_SCRIPT_URL);u.searchParams.set("action",a);u.searchParams.set("claveApi",cfg.API_KEY_SOCIOS);const r=await fetch(u);const d=await r.json();if(!d.ok)throw new Error(d.mensaje||"Error");return d}async function post(a,registro){const r=await fetch(cfg.APPS_SCRIPT_URL,{method:"POST",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify({action:a,claveApi:cfg.API_KEY_SOCIOS,registro})});const d=await r.json();if(!d.ok)throw new Error(d.mensaje||"Error");return d}function render(){E.lista.innerHTML=metodos.map((m,i)=>`<article class="metodo-admin" data-i="${i}"><header><div><strong>${esc(m.nombre)}</strong><small>${esc(m.id)}</small></div><select data-c="estado"><option value="ACTIVO" ${m.estado==="ACTIVO"?"selected":""}>ACTIVO</option><option value="INACTIVO" ${m.estado==="INACTIVO"?"selected":""}>INACTIVO</option></select></header><div class="metodo-admin-cuerpo"><label class="campo-metodo"><span>Nombre</span><input data-c="nombre" value="${esc(m.nombre)}"></label><label class="campo-metodo"><span>Tipo</span><input data-c="tipo" value="${esc(m.tipo)}"></label><label class="campo-metodo"><span>Moneda</span><select data-c="moneda"><option value="VES" ${m.moneda==="VES"?"selected":""}>VES</option><option value="USD" ${m.moneda==="USD"?"selected":""}>USD</option></select></label><label class="campo-metodo"><span>Banco o plataforma</span><input data-c="banco" value="${esc(m.banco)}"></label><label class="campo-metodo"><span>Titular</span><input data-c="titular" value="${esc(m.titular)}"></label><label class="campo-metodo"><span>Documento</span><input data-c="documento" value="${esc(m.documento)}"></label><label class="campo-metodo"><span>Teléfono</span><input data-c="telefono" value="${esc(m.telefono)}"></label><label class="campo-metodo"><span>Cuenta o Pay ID</span><input data-c="numeroCuenta" value="${esc(m.numeroCuenta)}"></label><label class="campo-metodo"><span>Correo</span><input data-c="correo" value="${esc(m.correo)}"></label><label class="campo-metodo"><span>Orden</span><input data-c="orden" type="number" min="1" value="${Number(m.orden||1)}"></label><label class="campo-metodo ancho"><span>Instrucciones adicionales</span><textarea data-c="datosAdicionales">${esc(m.datosAdicionales)}</textarea></label></div></article>`).join("");}function leer(){document.querySelectorAll(".metodo-admin").forEach(a=>{const m=metodos[Number(a.dataset.i)];a.querySelectorAll("[data-c]").forEach(c=>m[c.dataset.c]=c.value)});return metodos}async function cargar(){try{const d=await get("obtenerConfiguracionPagosTiendaMD20");const r=d.registro||{};E.tasa.value=r.tasaBs||"";E.mostrar.value=r.mostrarPrecioBs||"SI";E.max.value=String(r.maxComprobanteMb||5);E.fecha.textContent=r.fechaTasa||"Sin actualizar";if(r.carpetaUrl){E.carpeta.href=r.carpetaUrl;E.carpeta.hidden=false}metodos=r.metodos||[];render();E.estado.textContent="Conectado con Google Sheets";E.punto.classList.add("ok")}catch(e){console.error(e);E.estado.textContent="Error de conexión";aviso(e.message,true)}}async function guardar(){E.guardar.disabled=true;E.guardar.textContent="Guardando...";try{const d=await post("guardarConfiguracionPagosTiendaMD20",{tasaBs:E.tasa.value,mostrarPrecioBs:E.mostrar.value,maxComprobanteMb:E.max.value,metodos:leer()});aviso("Tasa y métodos actualizados correctamente.");await cargar()}catch(e){aviso(e.message,true)}finally{E.guardar.disabled=false;E.guardar.textContent="Guardar cambios"}}E.guardar.addEventListener("click",guardar);E.abrir?.addEventListener("click",()=>{E.menu.classList.add("abierto");E.capa.classList.add("visible")});E.cerrar?.addEventListener("click",()=>{E.menu.classList.remove("abierto");E.capa.classList.remove("visible")});E.capa?.addEventListener("click",()=>{E.menu.classList.remove("abierto");E.capa.classList.remove("visible")});E.salir?.addEventListener("click",()=>location.href="index.html");cargar()})();